package sv.edu.ues.vl23003.saldo.sync; import android.content.Context; import androidx.work.*; import java.util.concurrent.TimeUnit; public final class SyncManager {private SyncManager(){} public static void schedule(Context c){PeriodicWorkRequest r=new PeriodicWorkRequest.Builder(SyncWorker.class,1,TimeUnit.HOURS).build(); WorkManager.getInstance(c).enqueueUniquePeriodicWork("pizto_sync",ExistingPeriodicWorkPolicy.KEEP,r); } public static void programar(Context c){schedule(c);}}
